-- ===========================================================================
-- Tolaim — sample data
-- ===========================================================================
-- GENERATED FILE. Edit src/lib/data/seed-data.ts and run `npm run seed:gen`.
--
-- SAMPLE CONTENT — NOT A HALACHIC SOURCE. Every authority, rabbi, ruling and
-- alert below is invented for development. The organisation and rabbi names
-- are deliberately generic so nothing here can be mistaken for a real
-- published position. Replace all of it with reviewed content before launch:
--
--   delete from alerts; delete from rulings; delete from rabbis;
--   delete from authorities; delete from produce_items;
--
-- Everything is inserted as approved so a fresh project has a working public
-- site immediately. `approved_by` is null because no auth user exists yet.
-- ===========================================================================

begin;

-- Categories ---------------------------------------------------------------
on conflict (slug) do nothing;

-- Authorities --------------------------------------------------------------
on conflict (slug) do nothing;

-- Produce ------------------------------------------------------------------

If you have not been shown how to do this in person, buy pre-checked lettuce instead. This is the single most common item people believe they have cleaned properly and have not.', 'Infestation rises sharply in warm months and in field-grown rather than greenhouse supply.', null, 'Romaine lettuce', 2, 'approved', now()),
  ('iceberg-lettuce', 'Iceberg lettuce', array['Crisphead lettuce'], (select id from produce_categories where slug = 'leafy-greens'), 'The tight head protects the inner leaves, but the outer ones need real inspection.', 'Discard the outer leaves. Separate the remaining leaves, wash them, and inspect them against light. The inner core is generally clean, but do not assume the boundary between ''outer'' and ''inner'' — check until you have seen several consecutive clean leaves.', '', null, 'Iceberg lettuce', 3, 'approved', now()),
  ('spinach', 'Spinach', '{}', (select id from produce_categories where slug = 'leafy-greens'), 'Leaf miners tunnel inside the leaf itself, where washing cannot reach them.', 'Leaf miner damage shows as a pale winding trail inside the leaf. A leaf with visible trails is discarded — the insect is inside the leaf and no washing removes it. Wash the remaining leaves, then inspect each one against light for trails and for thrips along the stem.

Bagged ''triple-washed'' spinach has been washed, not inspected. It still requires checking unless it carries reliable supervision stating otherwise.', 'Leaf miner activity peaks in spring and early summer.', null, 'Spinach', 2, 'approved', now()),
  ('kale', 'Kale', array['Curly kale', 'Cavolo nero', 'Lacinato'], (select id from produce_categories where slug = 'leafy-greens'), 'The curled edges hold aphids tightly; flat-leaf varieties are easier.', 'Strip the leaves from the stems. Soak in cold soapy water and agitate vigorously — the curl is what makes this hard, and agitation is what dislodges what is caught in it. Rinse thoroughly, then inspect against light, opening out the curled edge as you go.

Flat-leaf varieties such as lacinato are meaningfully easier to check than curly kale.', '', null, 'Kale', 2, 'approved', now()),
  ('swiss-chard', 'Swiss chard', array['Silverbeet', 'Mangold'], (select id from produce_categories where slug = 'leafy-greens'), 'Both leaf miners and aphids; the thick stalk hides insects at the base.', 'Cut the leaf away from the stalk and treat the two separately. Discard leaves with miner trails. Wash and inspect the leaves against light. Split the stalks lengthwise and rinse the channel, which collects soil and insects.', '', null, 'Swiss chard', 2, 'approved', now()),
  ('arugula', 'Arugula', array['Rocket', 'Rucola'], (select id from produce_categories where slug = 'leafy-greens'), 'Small, tender leaves that hold aphids and are difficult to inspect one by one.', 'Soak in cold soapy water, agitate well, and rinse through a fine strainer. Because the leaves are small, inspect in small batches spread thinly on a light box rather than leaf by leaf. Check the strainer and the wash water — insects that were dislodged will be there.', '', null, 'Arugula', 2, 'approved', now()),
  ('parsley', 'Parsley', array['Flat-leaf parsley', 'Curly parsley'], (select id from produce_categories where slug = 'herbs'), 'Among the most heavily infested items in the produce aisle.', 'Cut the bunch free of its tie and separate the sprigs. Soak in cold soapy water for several minutes, agitating hard. Rinse through a fine cloth or mesh and examine what the cloth caught — for herbs this is the primary check, not an afterthought. Then inspect the sprigs themselves against light.

If the wash water comes back visibly dirty a second and third time, keep washing.', 'Consistently high year-round; not a seasonal item.', null, 'Parsley', 2, 'approved', now()),
  ('cilantro', 'Cilantro', array['Coriander leaf', 'Fresh coriander', 'Kusbara'], (select id from produce_categories where slug = 'herbs'), 'Similar to parsley and generally worse; the leaf shape traps insects.', 'Treat exactly as parsley: separate, soak in soapy water with hard agitation, filter the wash water through a cloth, inspect the cloth, then inspect the sprigs against light. Repeat the wash until the water runs clean.', '', null, 'Cilantro', 2, 'approved', now()),
  ('fresh-dill', 'Fresh dill', array['Dill weed'], (select id from produce_categories where slug = 'herbs'), 'The feathery fronds cannot be inspected reliably. Use dried or supervised frozen.', 'There is no home method that reliably clears fresh dill. The frond structure is too fine to inspect and too dense to wash through. Use dried dill, or frozen dill under reliable supervision, which is checked before freezing.

If a recipe calls for fresh dill, the supervised frozen product is the substitute — not a longer wash.', '', null, 'Fresh dill', 1, 'approved', now()),
  ('fresh-mint', 'Fresh mint', array['Nana', 'Spearmint', 'Peppermint'], (select id from produce_categories where slug = 'herbs'), 'Very heavily infested, and the textured leaf makes inspection unreliable.', 'Most authorities do not accept a home method for fresh mint. The leaf surface is ridged and matte, which hides insects that would be visible on a smooth leaf, and the plant is grown in conditions that favour infestation.

Use supervised pre-checked mint if you can find it; otherwise use dried.', '', null, 'Fresh mint', 1, 'approved', now()),
  ('basil', 'Basil', array['Sweet basil'], (select id from produce_categories where slug = 'herbs'), 'Thrips sit along the vein on the underside of the leaf.', 'Pick the leaves from the stems. Soak in cold soapy water, agitate, and rinse each leaf. Inspect the underside of every leaf against light, following the central vein — that is where thrips sit and they are the colour of the leaf.

Basil grown hydroponically under supervision is substantially cleaner and is the practical choice if you use it often.', '', null, 'Basil', 2, 'approved', now()),
  ('broccoli', 'Broccoli', '{}', (select id from produce_categories where slug = 'cruciferous'), 'The floret head is dense enough that insects inside it cannot be seen or reached.', 'Fresh broccoli heads cannot be checked by looking at them — the florets close over anything inside. The accepted method is to break the head into small florets, soak in warm soapy water long enough to drive insects out, agitate, and then filter and examine the wash water. This takes training to do reliably.

Frozen broccoli under reliable supervision is checked before freezing and is the ordinary choice for home kitchens.', 'Aphid loads rise in late summer and autumn.', null, 'Broccoli', 2, 'approved', now()),
  ('cauliflower', 'Cauliflower', '{}', (select id from produce_categories where slug = 'cruciferous'), 'Denser than broccoli and harder again; the head conceals everything inside it.', 'Cut the head into small florets — smaller than you think, because the point is to open the interior. Soak in warm soapy water, agitate hard, then filter the wash water through a cloth and examine it carefully. Repeat until the filter comes back clean.

Supervised frozen cauliflower is checked before freezing and avoids the whole procedure.', '', null, 'Cauliflower', 2, 'approved', now()),
  ('cabbage', 'Cabbage', array['Green cabbage', 'Red cabbage'], (select id from produce_categories where slug = 'cruciferous'), 'The tight head keeps the interior clean; the outer layers do not stay clean.', 'Remove and discard the outer leaves. Then peel off leaves one at a time, rinsing and checking each, until you reach leaves that are clean and tightly packed. From that point inward the head is generally reliable.

Check the base of each leaf where it met the core, which is where aphids collect.', '', null, 'Cabbage', 3, 'approved', now()),
  ('brussels-sprouts', 'Brussels sprouts', '{}', (select id from produce_categories where slug = 'cruciferous'), 'Small tight heads — the same problem as cabbage, at a scale that makes it slower.', 'Trim the base and remove the outer two or three leaves of each sprout. Halve or quarter them and rinse, checking the cut faces and between the remaining layers. Because each sprout is a separate head, this has to be done individually — there is no batch shortcut.', '', null, 'Brussels sprouts', 3, 'approved', now()),
  ('strawberries', 'Strawberries', '{}', (select id from produce_categories where slug = 'berries'), 'The seeded surface and the hull both hold insects, but they can be reached.', 'Cut off the green hull and a thin slice of the flesh beneath it — that hollow is the main problem area. Soak the berries in cold soapy water, agitate, and rinse each one under a stream of water while rubbing the surface with your thumb. Inspect the surface and the cut end against light.

Do not soak with the hull on; it traps what you are trying to remove.', 'Higher risk in peak local season; imported winter supply is usually cleaner.', null, 'Strawberries', 3, 'approved', now()),
  ('raspberries', 'Raspberries', '{}', (select id from produce_categories where slug = 'berries'), 'The hollow core and the gaps between drupelets cannot be cleared.', 'There is no reliable way to clean fresh raspberries. The berry is a cluster of small chambers around a hollow centre, and insects sit inside where neither water nor inspection reaches.

Use supervised frozen or processed raspberry product. A purée or preserve made under supervision has been dealt with before processing.', '', null, 'Raspberries', 1, 'approved', now()),
  ('blackberries', 'Blackberries', '{}', (select id from produce_categories where slug = 'berries'), 'Same structure as raspberries, with the same conclusion.', 'Not cleanable fresh, for the same reason as raspberries: the drupelet structure encloses spaces that cannot be reached or seen into. Use supervised frozen or processed product.', '', null, 'Blackberries', 1, 'approved', now()),
  ('blueberries', 'Blueberries', '{}', (select id from produce_categories where slug = 'berries'), 'Smooth-skinned and mostly clean, but the blossom end needs a look.', 'Rinse in a colander, agitating so the berries turn over. Spread them on a light surface and look over them — you are checking the small opening at the blossom end and for any berry that is soft or split. Discard damaged berries rather than trying to clean them.', '', null, 'Blueberries', 3, 'approved', now()),
  ('grapes', 'Grapes', array['Table grapes'], (select id from produce_categories where slug = 'fruit'), 'Generally clean; check where the fruit meets the stem.', 'Separate the grapes from the stem or open the bunch out, and rinse under running water. Look at the point where each grape attached to the stem and discard any that are split or mouldy. Bunches that arrive with visible webbing between the grapes are rejected rather than washed.', '', null, 'Grapes', 4, 'approved', now()),
  ('fresh-figs', 'Fresh figs', '{}', (select id from produce_categories where slug = 'fruit'), 'The fruit is hollow and its interior is not accessible for inspection.', 'Fresh figs cannot be checked without destroying the fruit, and opening every fig is not a practical method. Most authorities do not permit fresh figs without supervision.

Dried figs are a separate question — see the dried figs entry, where the fruit can be opened and looked at.', '', null, 'Fresh figs', 1, 'approved', now()),
  ('dried-figs', 'Dried figs', '{}', (select id from produce_categories where slug = 'dried-and-grains'), 'Open each fig and look inside; infestation happens in storage, not the field.', 'Tear or cut each fig open and look at the interior against good light. You are looking for small insects and for fine webbing, which is the clearer sign. A fig with webbing is discarded along with any others stored touching it.

Product that has been vacuum-packed or refrigerated since packing is markedly cleaner than loose bulk supply.', '', null, 'Dried figs', 3, 'approved', now()),
  ('dates', 'Dates', array['Medjool dates', 'Deglet Noor'], (select id from produce_categories where slug = 'dried-and-grains'), 'Open each date to remove the pit and look inside while you do.', 'You are already opening the date to remove the pit — do it in good light and look at the cavity and the flesh around it. Discard any date with visible insects, webbing, or a powdery residue.

Refrigerated or frozen supply is much less likely to be infested than dates kept at room temperature in bulk bins.', '', null, 'Dates', 3, 'approved', now()),
  ('rice', 'Rice', array['White rice', 'Basmati', 'Jasmine rice'], (select id from produce_categories where slug = 'dried-and-grains'), 'Spread it thin and look before cooking; storage pests are the concern.', 'Pour the rice in a thin layer onto a light-coloured tray and look across it — moving grains, small beetles, or clumped grains held together by webbing. Do this before the rice goes anywhere near the pot.

Rice kept sealed in a cool cupboard and used within a few months is rarely a problem. Long-stored open bags are where this shows up.', '', null, 'Rice', 3, 'approved', now()),
  ('celery', 'Celery', '{}', (select id from produce_categories where slug = 'vegetables'), 'Insects sit in the groove that runs the length of each stalk.', 'Separate the stalks from the base. Run your thumb down the inner groove of each stalk under running water — that channel is the whole issue. Check the leafy tops separately, or discard them; they are as infested as any leafy green.', '', null, 'Celery', 3, 'approved', now()),
  ('asparagus', 'Asparagus', '{}', (select id from produce_categories where slug = 'vegetables'), 'The overlapping scales at the tip hide insects and do not wash out.', 'Cut off the top inch or two, where the scales overlap tightly, and discard it. Rinse the remaining spear, rubbing along the shaft where smaller scales lie flat. Some authorities require the whole spear to be inspected under light after washing.', '', null, 'Asparagus', 2, 'approved', now()),
  ('artichoke', 'Globe artichoke', array['Artichoke'], (select id from produce_categories where slug = 'vegetables'), 'Layer upon layer of tightly packed leaves with no way to see between them.', 'Fresh whole artichokes are not accepted by most authorities. The bracts overlap so tightly that neither water nor light reaches between them, and taking the vegetable apart leaf by leaf is beyond what anyone does in practice.

Supervised frozen or jarred artichoke hearts are processed after checking and are the ordinary substitute.', '', null, 'Globe artichoke', 1, 'approved', now()),
  ('corn-on-the-cob', 'Corn on the cob', array['Sweetcorn'], (select id from produce_categories where slug = 'vegetables'), 'Strip the husk and silk and look at the tip, where the earworm enters.', 'Pull off the husk and all of the silk. Look at the tip of the cob — that is where corn earworm enters and where the damage is visible as chewed or discoloured kernels. Cut away any damaged section. Rinse the cob.', 'Earworm damage is most common in late-summer local corn.', null, 'Corn on the cob', 3, 'approved', now()),
  ('bell-peppers', 'Bell peppers', array['Capsicum', 'Sweet peppers'], (select id from produce_categories where slug = 'vegetables'), 'The outside is clean; cut it open and check the seed cavity.', 'Rinse the outside. Cut the pepper open and remove the seed core — look at the cavity and at the folds inside the flesh before you slice further. Discard any pepper with soft spots or entry holes on the skin.', '', null, 'Bell peppers', 3, 'approved', now()),
  ('cucumber', 'Cucumber', '{}', (select id from produce_categories where slug = 'vegetables'), 'Rinse it. Nothing further is required.', 'Rinse under running water. If the skin has soft spots or holes, cut them away or discard the cucumber — but ordinary graded supply needs nothing beyond a rinse.', '', null, 'Cucumber', 4, 'approved', now()),
  ('tomatoes', 'Tomatoes', array['Vine tomatoes', 'Cherry tomatoes'], (select id from produce_categories where slug = 'vegetables'), 'Rinse, and look at the stem scar.', 'Rinse under running water and glance at the scar where the stem attached, which is the one place anything collects. Split or mouldy fruit is discarded rather than washed.', '', null, 'Tomatoes', 4, 'approved', now()),
  ('carrots', 'Carrots', '{}', (select id from produce_categories where slug = 'root-and-bulb'), 'Scrub or peel. The root itself is not an infestation concern.', 'Scrub under running water or peel. Cut away any cracked or damaged section. The leafy tops, if attached, are treated as a leafy green and are usually discarded.', '', null, 'Carrots', 4, 'approved', now()),
  ('leeks', 'Leeks', '{}', (select id from produce_categories where slug = 'root-and-bulb'), 'Split lengthwise and rinse between the layers — soil and insects sit there.', 'Trim the root and the dark green tops. Split the leek lengthwise and fan the layers open under running water, rinsing between each one. The layers are sleeves and everything collects inside them; rinsing the outside does nothing.', '', null, 'Leeks', 3, 'approved', now()),
  ('scallions', 'Scallions', array['Spring onions', 'Green onions'], (select id from produce_categories where slug = 'root-and-bulb'), 'Same layered problem as leeks, at smaller scale.', 'Trim the roots and the tips. Split the green portion lengthwise and rinse inside the tube, where insects sit out of reach of a surface rinse. The white bulb needs its outer layer removed.', '', null, 'Scallions', 3, 'approved', now()),
  ('onions', 'Onions', array['Brown onions', 'Red onions'], (select id from produce_categories where slug = 'root-and-bulb'), 'Peel and use. Nothing is required.', 'Remove the papery skin and the first layer beneath it. Discard onions that are soft or have visible rot. Nothing further applies.', '', null, 'Onions', 5, 'approved', now()),
  ('potatoes', 'Potatoes', '{}', (select id from produce_categories where slug = 'root-and-bulb'), 'Scrub or peel; cut out any eyes or damage.', 'Scrub under running water or peel. Cut out sprouting eyes, green patches and any damaged flesh. There is no insect concern in sound potatoes.', '', null, 'Potatoes', 4, 'approved', now()),
  ('apples', 'Apples', '{}', (select id from produce_categories where slug = 'fruit'), 'Rinse, and cut out the core as you normally would.', 'Rinse under running water. Check the skin for entry holes — a small dark puncture usually means damage inside, and that apple is cut open or discarded. The core is removed in the ordinary course of eating.', '', null, 'Apples', 4, 'approved', now()),
  ('bananas', 'Bananas', '{}', (select id from produce_categories where slug = 'fruit'), 'Nothing required.', 'Peel and eat. The peel protects the fruit and there is no known concern.', '', null, 'Bananas', 5, 'approved', now()),
  ('avocado', 'Avocado', '{}', (select id from produce_categories where slug = 'fruit'), 'Nothing required beyond discarding fruit that is rotten inside.', 'Cut open and remove the pit. Discard flesh that is brown or rotten — that is a quality question, not an infestation one. Nothing else applies.', '', null, 'Avocado', 5, 'approved', now()),
  ('mushrooms', 'Mushrooms', array['Button mushrooms', 'Cremini', 'Portobello'], (select id from produce_categories where slug = 'vegetables'), 'Wipe or rinse; check the gills of open-cap varieties.', 'Wipe or rinse briefly. For open-cap varieties such as portobello, look at the gills underneath and discard any that are wet, dark and collapsing. Commercially grown mushrooms are raised in controlled conditions and are rarely a concern.', '', null, 'Mushrooms', 4, 'approved', now())
on conflict (slug) do nothing;

-- Positions ----------------------------------------------------------------
on conflict (produce_id, authority_id) do nothing;

