insert into authorities (slug, name, short_name, kind, region, description, website_url, sort_order, status, approved_at) values
  ('metropolitan-produce-council', 'Metropolitan Rabbinical Produce Council', 'MRPC', 'organization'::authority_kind, 'North America', 'Publishes a seasonal produce guide covering the North American supply, updated twice a year from its own inspection laboratory.', null, 10, 'approved', now()),
  ('institute-produce-inspection', 'Institute for Produce Inspection', 'IPI', 'organization'::authority_kind, 'Israel', 'Laboratory-based inspection body working primarily with Israeli-grown produce, where infestation patterns differ substantially from imported supply.', null, 20, 'approved', now()),
  ('rav-yechezkel-adler', 'Rav Yechezkel Adler', 'R. Adler', 'posek'::authority_kind, 'North America', 'Widely cited on questions of produce inspection. Positions are recorded from written responsa and from rulings given to the communities that follow him.', null, 30, 'approved', now()),
  ('sefer-bedikas-hamazon', 'Sefer Bedikas HaMazon', 'SBH', 'publication'::authority_kind, 'International', 'A standard reference work on food inspection, now in its second edition. Cited by page number throughout this site.', null, 40, 'approved', now()),
  ('northern-vaad', 'Northern Vaad HaKashrus', 'Northern Vaad', 'organization'::authority_kind, 'United Kingdom', 'Issues guidance for the British and Northern European supply, which draws on different growing regions than the North American market.', null, 50, 'approved', now())
insert into produce_items (slug, name, also_known_as, category_id, summary, cleaning_guidance, season_note, image_path, image_alt, site_risk_level, status, approved_at) values
  ('romaine-lettuce', 'Romaine lettuce', array['Cos lettuce'], (select id from produce_categories where slug = 'leafy-greens'), 'Heavily infested with thrips and aphids that sit deep in the rib of the leaf.', 'Separate every leaf from the head — nothing can be checked while the head is intact. Soak the leaves in cold water with a small amount of vegetable wash, agitate, then rinse each leaf individually under a strong stream of water. Inspect both sides of each leaf against a light box, paying particular attention to the white rib, where thrips lodge and are hard to see.
insert into rulings (produce_id, authority_id, risk_level, guidance, citation, effective_date, notes, status, approved_at) values
  ((select id from produce_items where slug = 'romaine-lettuce'), (select id from authorities where slug = 'metropolitan-produce-council'), 2, 'Leaf-by-leaf inspection over a light box after washing. Pre-checked product under reliable supervision is preferred for home use.', 'MRPC Produce Guide, 14th ed., §3.1', '2025-09-01'::date, '', 'approved', now()),
  ((select id from produce_items where slug = 'romaine-lettuce'), (select id from authorities where slug = 'institute-produce-inspection'), 1, 'Field-grown romaine from the Israeli supply is not recommended in its fresh form. Use greenhouse-grown product under supervision.', 'IPI Bulletin 41', '2025-06-15'::date, 'Applies to open-field supply. Greenhouse product is treated at level 2.', 'approved', now()),
  ((select id from produce_items where slug = 'romaine-lettuce'), (select id from authorities where slug = 'rav-yechezkel-adler'), 2, 'May be checked at home by someone who has been trained. Washing without inspection is not sufficient.', 'Responsa, vol. II §17', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'romaine-lettuce'), (select id from authorities where slug = 'sefer-bedikas-hamazon'), 2, 'Requires washing followed by inspection of each leaf against strong light.', 'Sefer Bedikas HaMazon, 2nd ed., p. 112', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'iceberg-lettuce'), (select id from authorities where slug = 'metropolitan-produce-council'), 3, 'Discard outer leaves, wash and inspect the remainder. Within reach of a careful home cook.', 'MRPC Produce Guide, 14th ed., §3.2', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'iceberg-lettuce'), (select id from authorities where slug = 'sefer-bedikas-hamazon'), 3, 'Outer leaves removed; remaining leaves washed and checked.', 'Sefer Bedikas HaMazon, 2nd ed., p. 115', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'iceberg-lettuce'), (select id from authorities where slug = 'northern-vaad'), 2, 'Recent UK supply has shown aphid presence well into the head. Treat as expert checking.', 'Northern Vaad Produce Notice 2026/02', '2026-02-10'::date, '', 'approved', now()),
  ((select id from produce_items where slug = 'spinach'), (select id from authorities where slug = 'metropolitan-produce-council'), 2, 'Discard leaves showing miner trails; inspect the rest leaf by leaf against light.', 'MRPC Produce Guide, 14th ed., §3.4', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'spinach'), (select id from authorities where slug = 'institute-produce-inspection'), 2, 'Requires trained inspection. Pre-checked frozen product is the practical option for home kitchens.', 'IPI Bulletin 39', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'spinach'), (select id from authorities where slug = 'rav-yechezkel-adler'), 2, 'Checking is possible at home for one who knows what miner damage looks like.', 'Responsa, vol. II §19', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'kale'), (select id from authorities where slug = 'metropolitan-produce-council'), 2, 'Soak, agitate, rinse and inspect. Curly varieties require particular care at the leaf edge.', 'MRPC Produce Guide, 14th ed., §3.6', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'kale'), (select id from authorities where slug = 'sefer-bedikas-hamazon'), 2, 'Washing with agitation followed by inspection.', 'Sefer Bedikas HaMazon, 2nd ed., p. 121', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'kale'), (select id from authorities where slug = 'northern-vaad'), 3, 'May be checked at home following the soak-and-agitate method.', 'Northern Vaad Produce Guide, p. 8', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'swiss-chard'), (select id from authorities where slug = 'institute-produce-inspection'), 2, 'Leaf and stalk checked separately. Trained inspection required.', 'IPI Bulletin 44', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'swiss-chard'), (select id from authorities where slug = 'metropolitan-produce-council'), 2, 'Expert checking. Leaves with miner damage are discarded rather than cleaned.', 'MRPC Produce Guide, 14th ed., §3.7', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'arugula'), (select id from authorities where slug = 'metropolitan-produce-council'), 2, 'Wash with agitation, filter the wash water, inspect in thin batches.', 'MRPC Produce Guide, 14th ed., §3.9', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'arugula'), (select id from authorities where slug = 'rav-yechezkel-adler'), 2, 'Checking the wash water is an acceptable primary method for small-leaf greens.', 'Responsa, vol. II §22', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'parsley'), (select id from authorities where slug = 'metropolitan-produce-council'), 2, 'Wash with agitation, filter, inspect the filter cloth, then inspect the sprigs.', 'MRPC Produce Guide, 14th ed., §4.1', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'parsley'), (select id from authorities where slug = 'institute-produce-inspection'), 1, 'Not recommended fresh. Use supervised pre-checked or frozen product.', 'IPI Bulletin 38', null, 'IPI''s position reflects the Israeli open-field supply specifically.', 'approved', now()),
  ((select id from produce_items where slug = 'parsley'), (select id from authorities where slug = 'sefer-bedikas-hamazon'), 2, 'Requires thorough washing and filtration of the wash water.', 'Sefer Bedikas HaMazon, 2nd ed., p. 138', null, '', 'approved', now()),
  ((select id from produce_items where slug = 'parsley'), (select id from authorities where slug = 'northern-vaad'), 2, 'Expert checking. Pre-checked product widely available and preferred.', 'Northern Vaad Produce Guide, p. 12', null, '', 'approved', now()),
