  ((select id from produce_items where slug = 'fresh-dill'), (select id from authorities where slug = 'metropolitan-produce-council'), 1, 'Not recommended in fresh form. Use dried or supervised frozen.', 'MRPC Produce Guide, 14th ed., §4.5', null, '', 'approved', now()),
